"""Create an offline searchable catalog from derived item facts only."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
items=json.loads((ROOT/'item-database.json').read_text())
html='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Предметы Пиратии — база сборки</title>
<style>body{font:16px system-ui;background:#101821;color:#e6edf4;margin:24px}h1{font-size:25px}input,select,button{font:inherit;background:#1d2c3b;color:inherit;border:1px solid #466079;padding:10px;border-radius:7px}input{width:min(480px,90%)}.bar{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.muted{color:#a3b5c6}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:9px;border-bottom:1px solid #2c3c4b;vertical-align:top}th{position:sticky;top:0;background:#182735}small{color:#a3b5c6}.good{color:#83d6aa}.warn{color:#f1c46e}.scroll{overflow:auto;max-height:70vh}a{color:#93c4ff}</style>
<h1>База предметов твоей Пиратии</h1><p class="muted">Названия из русского клиента, ID и параметры из серверной таблицы. Магазинные скины подтверждены диапазоном ID5000–5999 в скрипте слияния. Клиентские предметы без серверной записи отдельно помечены.</p>
<div class="bar"><input id="search" placeholder="ID или название: НЯ, ЗЯ, Мордо, меч…"><select id="category"><option value="all">Все предметы</option><option value="selected">Все товары пяти НПС</option><option value="skins">Скины одежды и оружия</option><option value="skin_weapons">Скины оружия</option><option value="wings">Крылья</option><option value="fairies">Феи, питание и плоды</option><option value="forge">Форж и ковка</option><option value="tickets">Билеты</option><option value="boosts">Опыт и удача</option><option value="client_only">Только в клиенте</option></select><select id="active"><option value="both">Есть на сервере и в клиенте</option><option value="any">Показать все записи</option></select></div>
<p id="count"></p><div class="scroll"><table><thead><tr><th>ID</th><th>Название</th><th>Тип / уровень</th><th>Магазин</th><th>Цена владельца</th><th>Наличие</th></tr></thead><tbody id="rows"></tbody></table></div><div class="bar"><button id="prev">Назад</button><span id="page"></span><button id="next">Далее</button></div>
<p class="muted">В комплекте также item-database.csv для Excel и item-database.sqlite3 для запросов. Новые цены выбранных ID синхронизируются в серверной и клиентской таблицах и действуют у обычных продавцов. В базе нет аккаунтов или паролей.</p>
<script>const items=__ITEMS__;const names={apparel:'Аппарели и крылья',fairies:'Феи и уход',forge:'Форж',tickets:'Билеты',boosts:'Опыт и удача'};const q=document.querySelector('#search'),cat=document.querySelector('#category'),active=document.querySelector('#active'),rows=document.querySelector('#rows');let page=0,filtered=[];const size=150;
function match(r,c){if(c==='all')return true;if(c==='selected')return !!r.shop;if(c==='skins')return r.apparel_id_range;if(c==='skin_weapons')return r.apparel_id_range&&r.kind<=11;if(c==='wings')return r.wings;if(c==='client_only')return !r.in_server;return r.shop===c}
function search(){let s=q.value.toLowerCase().trim();if(s==='ня')s='3844';if(s==='зя')s='3845';filtered=items.filter(r=>(active.value==='any'||r.in_server&&r.in_client)&&match(r,cat.value)&&(!s||(String(r.id)+' '+r.name_ru+' '+r.name_en+' '+r.effect_hooks).toLowerCase().includes(s)));page=0;draw()}
function cell(tr,text,cls){const td=document.createElement('td');td.textContent=text;if(cls)td.className=cls;tr.append(td);return td}
function draw(){rows.replaceChildren();for(const r of filtered.slice(page*size,(page+1)*size)){const tr=document.createElement('tr');cell(tr,r.id);const td=cell(tr,r.name_ru||r.name_en);const small=document.createElement('small');small.textContent=r.name_en;td.append(document.createElement('br'),small);cell(tr,r.kind+' / '+(r.level??'—'));cell(tr,names[r.shop]||'—');cell(tr,r.id===1000?'Выкуп НПС: 500 G':r.owner_price?new Intl.NumberFormat('ru-RU').format(r.owner_price)+' G':'—');cell(tr,r.in_server&&r.in_client?'Сервер + клиент':r.in_server?'Только сервер':'Только клиент',r.in_server&&r.in_client?'good':'warn');rows.append(tr)}document.querySelector('#count').textContent='Найдено: '+filtered.length+' из '+items.length;document.querySelector('#page').textContent=(page+1)+' / '+Math.max(1,Math.ceil(filtered.length/size));document.querySelector('#prev').disabled=!page;document.querySelector('#next').disabled=(page+1)*size>=filtered.length}
q.oninput=search;cat.onchange=()=>{if(cat.value==='client_only')active.value='any';search()};active.onchange=search;document.querySelector('#prev').onclick=()=>{page--;draw()};document.querySelector('#next').onclick=()=>{page++;draw()};search();</script></html>'''
(ROOT/'item-database.html').write_text(html.replace('__ITEMS__',json.dumps(items,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')),encoding='utf-8')
